actions.script:
// a recipient line split at commas and semicolons outside quotes and angle brackets, each part a chip
const chips = (text) => {
    const out = []
    let current = '', quote = false, angle = 0
    for (const ch of String(text || '')) {
        if (ch === '"') quote = !quote
        else if (ch === '<' && !quote) angle++
        else if (ch === '>' && !quote && angle > 0) angle--
        else if ((ch === ',' || ch === ';') && !quote && angle === 0) { if (current.trim()) out.push({value: current.trim()}); current = ''; continue }
        current += ch
    }
    if (current.trim()) out.push({value: current.trim()})
    return JSON.stringify(out)
}
const escape = (line) => line.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const text = String(bodyText || '').replace(/\r\n?/g, '\n')
const html = text.split(/\n{2,}/).filter((part) => part.trim()).map((part) => '<p>' + part.split('\n').map(escape).join('<br>') + '</p>').join('')
const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'send#Compose', parameters: {fromValue: fromValue || '', emailMessageId: emailMessageId || null,
    toJson: chips(toText), ccJson: chips(ccText), bccJson: chips(bccText), subject: subject ?? '', body: html, bodyText: text || null,
    quoteHtml: quoteHtml || null, parentEmailMessageId: parentEmailMessageId || null, isForward: String(isForward) === 'true',
    parentCommEventId: parentCommEventId || null, replyToSenderOnly: String(replyToSenderOnly) === 'true',
    recordEntity: recordEntity || null, recordId: recordId || null, holdSeconds: 0}}).call()?.result || {}
if (!ec.message.hasError()) ec.message.addMessage(out.message || ec.l10n.localize('Sent'), out.sendError ? 'warning' : 'success')

const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'get#ComposeData', parameters: {emailMessageId: emailMessageId || null,
    replyToEmailMessageId: replyToEmailMessageId || null, replyAll: String(replyAll) === 'true', replyToCommEventId: replyToCommEventId || null,
    replyToSender: String(replyToSender) === 'true', contactListId: contactListId || null, to: to || null, cc: cc || null, bcc: bcc || null,
    subject: subject || null, body: body || null, recordEntity: recordEntity || null, recordId: recordId || null}}).call()?.result || {}
const compose = ec.message.hasError() ? null : (out.compose || null)
ready = compose != null
// the body as text: paragraphs and line breaks kept, the tags and entities gone
const textOf = (html) => String(html || '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|li|h[1-6]|blockquote)>/gi, '\n\n')
    .replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&').replace(/\n{3,}/g, '\n\n').trim()
const line = (list) => Array.from(list || []).map((chip) => String(chip.value || '')).filter((value) => value).join(', ')
identityList = compose ? Array.from(compose.identityList || []).map((identity) => ({value: identity.value, label: identity.label || identity.value})) : []
const record = compose ? compose.record : null
recordText = record ? ec.l10n.localize('Files on') + ': ' + (record.title || record.recordId) : ''
quoteText = compose && compose.quoteHtml ? textOf(compose.quoteHtml) : ''
draft = compose ? {fromValue: compose.fromValue || (identityList.length ? identityList[0].value : ''), toText: line(compose.to), ccText: line(compose.cc),
    bccText: line(compose.bcc), subject: compose.subject || '', bodyText: textOf(compose.body), quoteHtml: compose.quoteHtml || '',
    emailMessageId: compose.emailMessageId || '', parentEmailMessageId: compose.parentEmailMessageId || '', isForward: compose.isForward ? 'true' : 'false',
    parentCommEventId: compose.parentCommEventId || '', replyToSenderOnly: compose.replyToSenderOnly ? 'true' : 'false',
    recordEntity: record ? record.recordEntityName : '', recordId: record ? String(record.recordId) : ''} : {}
const KIND = {draft: 'Draft', reply: 'Reply', replyAll: 'Reply all', replySender: 'Reply to the sender', forward: 'Forward'}
composeTitle = ec.l10n.localize(compose && KIND[compose.kind] ? KIND[compose.kind] : 'New message')
